54	  @Test
55	  public void testBuildOneChunkTree() throws Exception {
56	    // Seed the expected and actual trees with the same chunk.
57	    final long blockID = 1;
58	    ChunkInfo chunk = buildChunk(0, ByteBuffer.wrap(new byte[]{1, 2, 3}));
59	
60	    // Build the expected tree proto using the test code.
61	    ContainerProtos.ChunkMerkleTree chunkTree = buildExpectedChunkTree(chunk);
62	    ContainerProtos.BlockMerkleTree blockTree = buildExpectedBlockTree(blockID,
63	        Collections.singletonList(chunkTree));
64	    ContainerProtos.ContainerMerkleTree expectedTree = buildExpectedContainerTree(Collections.singletonList(blockTree));
65	
66	    // Use the ContainerMerkleTree to build the same tree.
67	    ContainerMerkleTree actualTree = new ContainerMerkleTree();
68	    actualTree.addChunks(blockID, Collections.singletonList(chunk));
69	
70	    // Ensure the trees match.
71	    ContainerProtos.ContainerMerkleTree actualTreeProto = actualTree.toProto();
72	    assertTreesSortedAndMatch(expectedTree, actualTreeProto);
73	
74	    // Do some manual verification of the generated tree as well.
75	    assertNotEquals(0, actualTreeProto.getDataChecksum());
76	    assertEquals(1, actualTreeProto.getBlockMerkleTreeCount());
77	
78	    ContainerProtos.BlockMerkleTree actualBlockTree = actualTreeProto.getBlockMerkleTree(0);
79	    assertEquals(1, actualBlockTree.getBlockID());
80	    assertEquals(1, actualBlockTree.getChunkMerkleTreeCount());
81	    assertNotEquals(0, actualBlockTree.getBlockChecksum());
82	
83	    ContainerProtos.ChunkMerkleTree actualChunkTree = actualBlockTree.getChunkMerkleTree(0);
84	    assertEquals(0, actualChunkTree.getOffset());
85	    assertEquals(CHUNK_SIZE, actualChunkTree.getLength());
86	    assertNotEquals(0, actualChunkTree.getChunkChecksum());
87	  }
